import {stopSpeech} from './play-media.mjs';
const clone=x=>structuredClone(x),own=(x,k)=>Object.hasOwn(x,k),ownerOK=x=>typeof x==='string'&&x.trim().length>0;
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const chapter=(s,id)=>s.chapters.find(c=>c.id===id),quote=(s,id)=>s.quotes.find(q=>q.id===id);
const label=c=>`Chapter ${c.number}: ${c.title}`;
const identity=row=>row?{left:row.left,right:row.right,kind:row.kind}:null;
let visit=null,disposeBinding=null;
export function resetChapterConnections(){disposeBinding?.();visit=null;}
function makeSlot(source,work,initialize=false,template){const s=clone(source),w=initialize?newChapterWork(s):clone(work),view=readChapterWork(s,w);return {source:s,work:w,template:template===undefined?undefined:clone(template),status:'',ui:{turn:'map',inspectedChapter:view.preview?.selected??s.chapters[0].id,left:view.preview?.left??null,right:view.preview?.right??null,kind:view.preview?.kind??null,disclosures:new Map(),quoteId:s.quotes[0]?.id??null,quoteReturn:null,linkPage:0,referencePage:0,frame:0,invitation:0,selectedLink:null,help:null,helpReturn:'map',sourceOpen:false}};}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){disposeBinding?.();const source=chapterSource();visit={book,owner,active:source.id,screen:'draft',card:null,drafts:new Map([[source.id,makeSlot(source,null,true)]]),copies:new Map(),readonly:new Map(),page:null,bound:null,binding:null};}return visit;}
const current=v=>v.screen==='draft'?v.drafts.get(v.active):v.screen==='card'?v.readonly.get(v.card):null;
const editable=(v,a)=>v.screen==='draft'&&!!a&&readChapterWork(a.source,a.work).status==='ready';
const external=(url,text,attrs='')=>`<a ${attrs} href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`;
const flags=(a,id)=>a.ui.disclosures.get(id)??{plot:false,notice:false,further:false};
