function bookMap(a){const s=a.source,u=a.ui;return `<div class="cm-map" data-cm-map role="region" aria-label="Chapters in book order" tabindex="0">${s.chapters.map(c=>{const inspected=u.inspectedChapter===c.id,left=u.left===c.id,right=u.right===c.id,tags=[...(inspected?['Inspecting']:[]),...(left?['Left']:[]),...(right?['Right']:[])];return `<button type="button" data-cm-chapter="${esc(c.id)}" aria-label="${esc(`${label(c)}${tags.length?'. '+tags.join(', '):''}`)}" aria-pressed="${inspected}" class="cm-node${inspected?' cm-inspected':''}${left?' cm-left':''}${right?' cm-right':''}"><span class="cm-node-number">${c.number}</span><span class="cm-node-name">${esc(c.mapLabel)}</span><span class="cm-node-tags">${esc(tags.join(' · '))}</span></button>`;}).join('')}</div>`;}
function mapPage(a,readOnly){return `<section data-cm-surface="map"><h2 id="cm-title" tabindex="-1">Book map</h2><p>Chapter order shows where parts sit in this book, not when events happened. Every chapter is open.</p>${bookMap(a)}${chapterCard(a,a.ui.inspectedChapter,'map',{pin:true,readonly:readOnly})}</section>`;}
