 const token={};v.bound=root;v.binding=token;const a=current(v),source=a?.source,screen=v.screen,active=v.active,card=v.card,route=location.hash,controls=[root,...root.querySelectorAll('button,a,details,summary,select,[data-speak]')],invalid=new Set(),chains=new Map();
